def valid_parentheses(s: str) -> bool:
    # Initialize a stack to keep track of opening brackets
    stack = []

    # Iterate over each character in the string
    for char in s:
        if char == '(':
            # If the opening bracket is encountered, push it onto the stack
            stack.append(char)
        elif char == ')':
            # If a closing bracket is encountered, check if there's a matching opening bracket
            if stack and stack.pop() == '(':
                # If there's a matching opening bracket, pop it from the stack
            else:
                # If there's no matching opening bracket, return False
                return False

    # If the stack is empty, all opening brackets had matching closing brackets
    return len(stack) == 0
